function teacherTurn(ctx,s){
var t=ctx.teacher;
if(!t|| !t.alive)return;
var n=1+(ctx.present().length>8?1:0)+(ctx.rng()<0.5?1:0);
var used={};
for(var i=0;i<n;i++){
var e=HK.weighted(ctx.rng,TE,function(x){return used[x.id]?0:x.w(ctx,t);});
if(!e)break;
used[e.id]=1;
e.run(ctx,t);
ctx.flush();
}
}
