var f=ctx.most(ctx.present().filter(function(o){return o!==c&& !o.flags.teacher&&R(ctx,o,c).aff>25&& !(B&&B.join.indexOf(o.i)>=0)&& !(B&&B.by===o.i);}),function(o){return R(ctx,o,c).aff/60+o.tr.np*0.5;});
